"Every prayer as an illustrated prayer card. Choose a topic, then open a card to pray it, save it, or print it.": "Кожна молитва — ілюстрована картка. Оберіть тему й відкрийте картку, щоб помолитися, зберегти чи надрукувати її.",
"The prayer St. Ignatius never wanted his companions to skip: five short steps to look back on the day with God.": "Молитва, яку святий Ігнатій ніколи не дозволяв пропускати своїм співбратам: п’ять коротких кроків, щоб озирнутися на день разом із Богом.",
"Gregorian chant and beloved Catholic hymns, with recordings and the words in Latin and English: the Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles, and more.": "Григоріанський хорал і улюблені католицькі гімни із записами та текстами латиною й англійською: Salve Regina, Pange Lingua, Veni Creator, Adeste Fideles та інші.",
"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "Часи Пресвятої Діви, від Утрені до Повечір’я, за порами року. Улюблена молитва богопосвячених, терціаріїв і тих, хто носить коричневий скапулярій.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Коричневий і зелений скапулярії, Чудотворний медалик і медалик святого Бенедикта, перші п’ятниці й перші суботи, свячена вода: що це, як це зберігати й молитви.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "Давня молитва про Воплочення, яку промовляють уранці, опівдні й увечері. У пасхальний час — Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Моліться уривком Писання, як ченці: читайте, роздумуйте, відповідайте й відпочивайте в Бозі.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Ведіть особистий щоденник щоденної молитви, формуйте звичку й дивіться на свою вірність тиждень за тижнем.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Кожна частина меси по черзі: коли стояти, сидіти й ставати на коліна, і що означає кожна мить. Стежте з телефона під час меси.",
"Every pope from St. Peter to Leo XIV, century by century.": "Усі папи від святого Петра до Лева XIV, століття за століттям.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "Великі ордени Церкви: ченці, каноніки, жебрущі брати, регулярні клірики, сестри й лицарські ордени хрестових походів.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Найвідоміші ікони Сходу й Заходу: що вони зображають і їхні історії.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "Двадцять три Східні католицькі Церкви в повній єдності з Римом: їхні традиції, предстоятелі й землі.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Як стати католиком чи повернутися до Церкви, основи щоденного католицького життя й порадники з розпізнавання та проживання кожного покликання: подружжя, священство, богопосвячене життя та інші.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Переліки, які вивчає кожен католик, із поясненнями: Десять заповідей, Заповіді блаженства, церковні заповіді, Таїнства, чесноти, діла милосердя, головні гріхи та інші.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Прогулянка католицьким храмом: для чого кожна його частина, священний посуд, ризи, кольори літургійних періодів і як брати участь у месі.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Усі двадцять один Вселенський собор, від Нікейського до II Ватиканського: коли й де вони відбувалися та чого навчав кожен.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Короткі й ясні визначення слів католицької віри, від «розрішення» до «Вульгати».",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "Слова святих, від Отців Церкви до наших днів, кожне з джерелом. Шукайте, переглядайте за темами й діліться улюбленими.",
"Pick as many answers as you like: your name, your work, your needs, and what you love in a saint. Sanctify suggests friends in heaven who fit.": "Оберіть скільки завгодно відповідей: ваше ім’я, роботу, потреби й те, що вам дороге у святих. Sanctify запропонує друзів на небі, які вам пасують.",
"Trusted places to keep learning about the faith: Church documents, Scripture and prayer, podcasts, video, courses, and more.": "Надійні місця, щоб далі вивчати віру: церковні документи, Писання й молитва, подкасти, відео, курси та інше.",
"Share prayer requests, ask questions about the faith, and talk about the saints and good books with other Sanctify members.": "Діліться проханнями про молитву, ставте питання про віру й розмовляйте про святих і добрі книги з іншими учасниками Sanctify.",
"Start a new conversation in the Community.": "Почніть нову розмову в спільноті.",
"Lives, patronages, and prayers of intercession for the saints.": "Житія, покровительство й молитви про заступництво святих.",
