"{n} saints with their lives and prayers, {n} quotes in their own words, and a patron finder.": "{n} святих із житіями й молитвами, {n} цитат їхніми власними словами й пошук покровителя.",
"{n} events of Church history, every pope, the religious orders, the great icons, and the Eastern Churches.": "{n} подій історії Церкви, усі папи, ордени, великі ікони та Східні Церкви.",
"The whole Bible, {n} books from the Church Fathers to today, and reading plans.": "Уся Біблія, {n} книг від Отців Церкви до наших днів і плани читання.",
"{n} teachings with Scripture and the Catechism, the Mass explained, and a glossary.": "{n} учень із Писанням і Катехизмом, пояснення меси й словник.",
"Every feast and season, with the saint of the day and the liturgical color.": "Кожне свято й період, зі святим дня та літургійним кольором.",
"Share prayer requests and talk about the faith with other members, here and on Discord.": "Діліться проханнями про молитву й розмовляйте про віру з іншими — тут і в Discord.",
"A saint, a verse, a prayer, and the Rosary mysteries for today, fresh every morning.": "Святий, вірш, молитва й таїнства вервиці на сьогодні — щоранку наново.",
