"Walk with Jesus through Matthew, Mark, Luke, and John in a month, about three chapters a day, with your progress saved.": "Пройдіть з Ісусом через Матея, Марка, Луку й Івана за місяць, приблизно по три розділи на день, зі збереженням поступу.",
