"Reduce motion": "Зменшити рух",
"Pages appear without sliding or fading in.": "Сторінки з’являються без зсуву й плавного проявлення.",
"Your data": "Ваші дані",
"Your saved entries, novenas, intentions, prayer record, badges, and settings are kept only in this browser. Save a backup to move them to another device.": "Ваші збережені записи, новени, наміри, молитовний щоденник, відзнаки й налаштування зберігаються лише в цьому браузері. Збережіть резервну копію, щоб перенести їх на інший пристрій.",
"Download a backup": "Завантажити резервну копію",
"Restore a backup": "Відновити з копії",
"Clear recently viewed": "Очистити нещодавно переглянуте",
