"How to pray the Rosary": "Як молитися на вервиці",
"On the crucifix, make the Sign of the Cross and pray the Apostles’ Creed.": "На розп’ятті перехрестіться й відмовте Апостольський Символ віри.",
"On the first large bead, pray the Our Father.": "На першому великому зерні відмовте «Отче наш».",
"On the next three beads, pray a Hail Mary each for faith, hope, and charity, then the Glory Be.": "На наступних трьох зернах відмовте по «Радуйся, Маріє» за віру, надію й любов, потім «Слава Отцю».",
"Announce the first mystery, and pray the Our Father on the large bead.": "Оголосіть перше таїнство й відмовте «Отче наш» на великому зерні.",
"On the ten small beads, pray ten Hail Marys while meditating on the mystery.": "На десяти малих зернах відмовте десять «Радуйся, Маріє», роздумуючи над таїнством.",
"End the decade with the Glory Be and the Fatima Prayer. Repeat for the other four mysteries.": "Завершіть десяток «Слава Отцю» й Фатімською молитвою. Повторіть для інших чотирьох таїнств.",
"At the centerpiece, finish with the Hail, Holy Queen and the closing prayer.": "На центральній ланці завершіть молитвою «Радуйся, Царице» й заключною молитвою.",
