"Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.": "Ведіть список людей і потреб, за які ви молитеся. Коли молитву вислухано, позначте це й подякуйте.",
"Tap ☆ Save on any prayer, saint, book, or article to keep it here.": "Натисніть ☆ Зберегти на будь-якій молитві, святому, книзі чи статті, щоб тримати їх тут.",
