"Passion Sunday": "Неділя Страстей",
"The Seven Sorrows of the Blessed Virgin Mary": "Сім болестей Пресвятої Діви Марії",
"Holy Saturday": "Велика субота",
"Easter Sunday: the Resurrection of Our Lord": "Великдень: Воскресіння Господа нашого",
"Low Sunday": "Провідна неділя",
"The Vigil of the Ascension": "Навечір’я Вознесіння",
"The Ascension of Our Lord": "Вознесіння Господа нашого",
"Sunday after the Ascension": "Неділя після Вознесіння",
"The Vigil of Pentecost": "Навечір’я П’ятидесятниці",
"Pentecost Sunday": "П’ятидесятниця",
"The Most Holy Trinity": "Пресвята Трійця",
"The Most Sacred Heart of Jesus": "Пресвяте Серце Ісуса",
"Our Lord Jesus Christ the King": "Господь наш Ісус Христос Цар",
"The Commemoration of All the Faithful Departed (All Souls)": "Поминання всіх вірних померлих",
"Twenty-Fourth and Last Sunday after Pentecost": "24-а й остання неділя після П’ятидесятниці",
"The Sunday within the Octave of Christmas": "Неділя в октаві Різдва",
"Fridays are days of penance throughout the year.": "П’ятниці протягом усього року — дні покути.",
"The Lord’s Day: Mass is an obligation for Catholics.": "День Господній: участь у месі обов’язкова для католиків.",
"A day of fasting and abstinence.": "День посту і стриманості.",
"A Friday of Lent: a day of abstinence from meat.": "П’ятниця Великого посту: день стриманості від м’яса.",
"Kept on the Sunday between the Octave Day of Christmas and the Epiphany, or else on January 2.": "Святкується в неділю між октавою Різдва і Богоявленням, інакше 2 січня.",
"The First Sunday after the Epiphany.": "Перша неділя після Богоявлення.",
"The name means “seventieth,” counting toward Easter. The Gloria and Alleluia fall silent, and violet is worn until Easter.": "Назва означає «сімдесятий» — відлік днів до Пасхи. Gloria і Алилуя замовкають, і до Пасхи використовується фіолетовий колір.",
"Lent begins. Ashes are blessed and imposed: “Memento, homo, quia pulvis es, et in pulverem reverteris.”": "Починається Великий піст. Попіл освячують і посипають: «Memento, homo, quia pulvis es, et in pulverem reverteris».",
"An Ember Day: by tradition a day of fasting and prayer for the season, and for those to be ordained.": "День Чотирьох пір року: за традицією день посту й молитви за пору року і за тих, хто готується до свячень.",
"Named from the first word of its Introit, “Rejoice.” Rose vestments may be worn.": "Назва — за першим словом інтроїту: «Радійте». Можна вдягати рожеві ризи.",
"Passiontide begins, and the crosses and images in the church are veiled.": "Починається час Страстей, і хрести та образи в храмі закривають.",
"Commemorated on the Friday after Passion Sunday.": "Згадуються в п’ятницю після неділі Страстей.",
"The Second Sunday of the Passion. Palms are blessed and carried in procession.": "Друга неділя Страстей. Освячують пальмові гілки й несуть їх у процесії.",
"The Mass of the Lord’s Supper, the washing of feet, and the stripping of the altars.": "Меса Тайної вечері, обмивання ніг і оголення престолів.",
"The solemn afternoon liturgy of the Passion, with the adoration of the Cross. No Mass is said.": "Урочиста пообідня літургія Страстей із поклонінням Хресту. Меса не служиться.",
"The Easter Vigil is kept at night.": "Пасхальне чування звершується вночі.",
"The feast of feasts.": "Свято свят.",
"Within the octave of Easter.": "В октаві Пасхи.",
"The Octave Day of Easter (Dominica in Albis).": "Октава Пасхи (Dominica in Albis).",
"The Lesser Litanies: the Litany of the Saints is chanted, traditionally in procession, to ask God’s blessing on the fields.": "Малі літанії: співається Літанія до всіх святих, за традицією в процесії, з проханням про Боже благословення на поля.",
"Forty days after Easter. The Paschal candle is extinguished after the Gospel.": "Через сорок днів після Пасхи. Після Євангелія гасять пасхальну свічку.",
"The descent of the Holy Spirit upon the apostles.": "Зішестя Святого Духа на апостолів.",
"Within the octave of Pentecost.": "В октаві П’ятидесятниці.",
"The First Sunday after Pentecost.": "Перша неділя після П’ятидесятниці.",
"The feast of the Most Holy Body of Christ, with its procession of the Blessed Sacrament.": "Свято Пресвятого Тіла Христового з процесією зі Святими Тайнами.",
"The Friday after the octave of Corpus Christi.": "П’ятниця після октави свята Тіла Христового.",
"Its Gospel speaks of the end of the world and the coming of the Son of Man.": "Її Євангеліє говорить про кінець світу і прихід Сина Людського.",
"Kept on the last Sunday of October. Instituted by Pope Pius XI in 1925.": "Святкується в останню неділю жовтня. Встановлене папою Пієм XI 1925 року.",
"Every priest may say three Masses for the dead.": "Кожен священник може відслужити три меси за померлих.",
"Every priest may say three Masses for the dead. Kept on November 3 this year, because November 2 is a Sunday.": "Кожен священник може відслужити три меси за померлих. Цього року — 3 листопада, бо 2 листопада припадає на неділю.",
