"Sanctify is made and looked after by a small team, and kept friendly by its moderators.": "Sanctify створює й підтримує невелика команда, а модератори зберігають дружню атмосферу.",
"Administrator": "Адміністратор",
"The Community": "Спільнота",
"Thank you to everyone who posts, prays for others, and writes in the Community Wiki. Many of the changes in Sanctify 0.9 began as members’ suggestions in the forum.": "Дякуємо всім, хто пише, молиться за інших і пише у вікі спільноти. Багато змін у Sanctify 0.9 почалися з пропозицій учасників на форумі.",
"Scripture and the Catechism": "Святе Письмо й Катехизм",
"The Bible on the site is the Douay-Rheims, with Bishop Challoner’s notes, which is in the public domain. The Catechism of the Catholic Church is © Libreria Editrice Vaticana.": "Біблія на сайті — Douay-Rheims із примітками єпископа Челлонера, вона в суспільному надбанні. Катехизм Католицької Церкви © Libreria Editrice Vaticana.",
"Images and recordings": "Зображення й записи",
"Pictures of the saints, icons, and books, and the hymn recordings, come from Wikipedia and Wikimedia Commons. Each one is credited on the site with its author and license.": "Зображення святих, ікони, книжки й записи гімнів узято з Wikipedia та Wikimedia Commons. Для кожного на сайті вказано автора й ліцензію.",
"Languages": "Мови",
"Sanctify is translated by hand into Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian, with the common prayers in the words Catholics pray in each language.": "Sanctify вручну перекладено іспанською, польською, французькою, португальською, італійською, німецькою, російською та українською мовами, а спільні молитви подано тими словами, якими моляться католики кожною мовою.",
"Type": "Шрифти",
"The headings are set in Cormorant Garamond and the text in Source Serif 4, both from Google Fonts under the SIL Open Font License.": "Заголовки набрано шрифтом Cormorant Garamond, текст — Source Serif 4; обидва з Google Fonts за ліцензією SIL Open Font License.",
