"What moderators can do": "Що можуть модератори",
"Reports:": "Скарги:",
"members can report a post or reply. Review them here, then remove it or dismiss the report.": "учасники можуть поскаржитися на допис чи відповідь. Розгляньте скарги тут і приберіть вміст або відхиліть скаргу.",
"Accounts:": "Облікові записи:",
"see every account with its posts and replies, ban a member for a day, a week, a month, or for good, and remove everything they have posted.": "переглядати кожен обліковий запис із його дописами й відповідями, блокувати учасника на день, тиждень, місяць чи назавжди й прибирати все, що він написав.",
"Members:": "Учасники:",
"mute a member so they can read and pray but not post, send them a private warning, and keep private notes on their account.": "заглушити учасника, щоб він міг читати й молитися, але не писати, надіслати йому особисте попередження й вести закриті нотатки про його обліковий запис.",
"Threads:": "Теми:",
"open any Community post to remove it, pin it to the top, lock it so it takes no new replies, or move it to another category.": "відкрити будь-який допис спільноти, щоб прибрати його, закріпити вгорі, закрити для нових відповідей чи перенести до іншої категорії.",
"Settings:": "Налаштування:",
