"AutoMod": "AutoMod",
"Turns back spam before it’s posted, in posts, replies, descriptions, and wiki pages: links to other sites from accounts less than a day old, more than four links, writing in all capitals, long runs of one character, and the same text posted twice within an hour. Moderators aren’t affected. Everything it does is in the log.": "Відсікає спам до публікації в дописах, відповідях, описах і сторінках вікі: посилання на інші сайти від облікових записів, молодших за добу, понад чотири посилання, текст великими літерами, довгі повтори одного символу й однаковий текст двічі за годину. На модераторів не діє. Усе, що він робить, записується в журнал.",
"Hide a post or reply until a moderator looks at it once": "Приховувати допис чи відповідь до перевірки модератором, коли на нього поскаржаться",
"different members report it.": "різних учасників.",
"Blocked words": "Заборонені слова",
